import * as THREE from 'three';import {createToyKit,disposeToyTree} from '../world/toy-kit.js';import {createShellGeometry} from '../world/gathering-scene.js';import {createAutumnLeafGeometry,createAutumnLeafMaterial} from '../world/autumn-leaf-geometry.js';import {createKeepsake} from './keepsake-view.js';
export function createPreparationSession({scene,zoneRoot,player,model,poser,recipeId,roomId,visual,reduced=false}){
 const saved={parent:player.parent,position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),pose:poser.getState(),children:player.children.map(o=>[o,o.visible]),old:[]};
 const root=new THREE.Group();root.name='gathered-preparation';let alive=true,borrowed=false,pendingGeometry=null,pendingMaterial=null;
 function dispose(){if(!alive)return;alive=false;try{if(borrowed){if(saved.parent)saved.parent.add(player);else player.removeFromParent();player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);}}finally{for(const[o,v]of [...saved.children,...saved.old])o.visible=v;pendingGeometry?.dispose();pendingMaterial?.dispose();disposeToyTree(root);}}
 try{zoneRoot.add(root);const k=createToyKit(root),{box,sphere,cylinder}=k,shell=recipeId==='shell-frame',leaf=recipeId==='leaf-frame',frame=shell||leaf,workshop=roomId==='workshop',z=workshop?-1.4:-2.04,top=workshop?1.155:1.185;
 if(!workshop)for(const mesh of Object.values(visual?.kitchen??{}).flat())if(mesh?.isObject3D){saved.old.push([mesh,mesh.visible]);mesh.visible=false;}
 if(workshop){const previous=zoneRoot.getObjectByName('workshop.process');if(previous){saved.old.push([previous,previous.visible]);previous.visible=false;}}
 const step=box(1.4,.49,.85,'#a8bca1',0,.245,z+1.02,.055);step.name='preparation.step';box(1.42,.035,.87,'#d6dec0',0,.507,z+1.02,.03);
 box(1.55,.045,.74,'#e6d1a8',0,top+.025,z+.2,.035);const bowl=cylinder(.32,.25,.18,'#89ada7',-.425,top+.13,z+.37),filling=cylinder(.27,.23,.04,frame?'#dfbfa2':'#e8c17d',-.425,top+.235,z+.37);bowl.visible=!frame;filling.visible=false;
 const rawFrame=box(.72,.045,.48,'#b99576',-.425,top+.08,z+.37,.025);rawFrame.visible=frame;
 const leafGeometry=leaf?(pendingGeometry=createAutumnLeafGeometry()):null,leafMaterial=leaf?(pendingMaterial=createAutumnLeafMaterial()):null,handProp=leaf?new THREE.Mesh(leafGeometry,leafMaterial):shell?new THREE.Mesh(createShellGeometry(),k.mat('#e5b199')):sphere(.13,'#cd7d67',0,0,0);if(frame){root.add(handProp);pendingGeometry=pendingMaterial=null;}handProp.name='preparation.held-material';
 const spoon=new THREE.Group();spoon.name='preparation.spoon';root.add(spoon);cylinder(.018,.018,.36,'#9a7855',0,-.16,0,spoon);sphere(.065,'#9a7855',0,-.34,0,1,.30,1.25,spoon);spoon.visible=false;
 const placed=[];for(let i=0;i<3;i++){const m=leaf?new THREE.Mesh(leafGeometry,leafMaterial):shell?new THREE.Mesh(createShellGeometry(),k.mat(['#e5b199','#efddba','#dca08d'][i])):sphere(.10,'#cd7d67',0,0,0);if(frame)root.add(m);m.position.set(-.62+i*.20,top+(leaf?.104:frame?.13:.30),z+.37);if(frame){m.scale.setScalar(.58);if(leaf)m.rotation.y=(i-1)*.45;}m.name='preparation.placed.'+i;m.visible=false;placed.push(m);}
 const finished=createKeepsake(recipeId);finished.position.set(.58,top+.05,z+.2);if(leaf)finished.rotation.y=Math.PI;finished.visible=false;root.add(finished);
 borrowed=true;zoneRoot.add(player);player.position.set(0,.53,z+1.02);player.rotation.set(0,Math.PI,0);player.scale.setScalar(1);model.position.set(0,0,0);model.quaternion.identity();model.scale.setScalar(1);for(const[c]of saved.children)if(c!==model)c.visible=false;
 const camera=new THREE.OrthographicCamera(-2.4,2.4,1.8,-1.8,.05,80);root.updateWorldMatrix(true,true);camera.position.copy(root.localToWorld(new THREE.Vector3(-2.8,3.8,z-1.5)));camera.lookAt(root.localToWorld(new THREE.Vector3(0,1.25,z+.60)));
 let state=null,done=false,clock=0,lastPose='';const hand=new THREE.Vector3(),target=new THREE.Vector3(-.425,top+.16,z+.37);
 function draw(){if(!alive||!state)return;const pose=state.busy&&state.step===0?'cookPour':state.busy?'cookMix':'cookReady',t=reduced?0:Math.floor(clock*12)/12,key=pose+'|'+(state.busy?t:0);if(key!==lastPose){poser.setPose(pose,1,state.busy?t:0);lastPose=key;}player.updateWorldMatrix(true,true);root.updateWorldMatrix(true,true);hand.fromArray(poser.getAnchors().rightHand);player.localToWorld(hand);root.worldToLocal(hand);handProp.position.copy(hand);handProp.visible=!done&&state.busy&&(frame||state.step===0);spoon.visible=!done&&!frame&&state.busy&&state.step===1;spoon.position.copy(hand);spoon.quaternion.setFromUnitVectors(new THREE.Vector3(0,-1,0),target.clone().sub(hand).normalize());
  const count=done?0:state.step>=2?3:state.step===1?state.busy?Math.floor(state.elapsed/2*3):0:0;placed.forEach((m,i)=>m.visible=frame?i<count:!done&&state.step>=1);filling.visible=!frame&&!done&&state.step>=1;finished.visible=done;root.updateWorldMatrix(true,true);
 }
 return {root,camera,scene,update(next,complete=false){state=next;done=complete;draw();},tick(dt){if(!alive||!state?.busy)return;clock+=Math.min(.1,Math.max(0,dt));draw();},fit(width,height){const aspect=Math.max(.25,width/height),span=Math.max(2.9,4.1/aspect);Object.assign(camera,{left:-span*aspect/2,right:span*aspect/2,top:span/2,bottom:-span/2});camera.updateProjectionMatrix();},dispose};}catch(error){dispose();throw error;}
}
